import type { CommandInvokeOptions } from '$PUBLIC';
const options: CommandInvokeOptions = { signal: new AbortController().signal };
const signal: AbortSignal | undefined = options.signal;
void signal;

import type { CommandInvokeOptions } from '$PUBLIC';
import type { ShellInvokeOptions } from '$SHELL';
const internal: ShellInvokeOptions = { signal: new AbortController().signal };
const publicOptions: CommandInvokeOptions = internal;
const back: ShellInvokeOptions = publicOptions;
// @ts-expect-error signal is readonly
back.signal = new AbortController().signal;

import type { CommandInvokeOptions } from '$PUBLIC';
const good: CommandInvokeOptions = { signal: new AbortController().signal };
// @ts-expect-error null is not a signal
const badNull: CommandInvokeOptions = { signal: null };
// @ts-expect-error numeric value is not a signal
const badNumber: CommandInvokeOptions = { signal: 1 };
// @ts-expect-error controller is not its signal
const badController: CommandInvokeOptions = { signal: new AbortController() };
// @ts-expect-error lookalike is incomplete
const badObject: CommandInvokeOptions = { signal: { aborted: false, reason: undefined } };
void good; void badNull; void badNumber; void badController; void badObject;

import type { CommandContext, CommandInvokeOptions } from '$PUBLIC';
declare const context: CommandContext;
context.invoke?.('true', []);
context.invoke?.('true', [], undefined);
const prior: CommandInvokeOptions = { cwd: '/', env: { VALUE: 'x' }, replaceEnv: true, stdinIsDefault: false };
context.invoke?.('true', [], prior);
const projected: AbortSignal | undefined = prior.signal;
void projected;

import type { CommandContext, CommandResult, ByteSource, ByteSink } from '$PUBLIC';
declare const context: CommandContext;
declare const input: ByteSource;
declare const output: ByteSink;
if (context.invoke) {
 const result: Promise<CommandResult> = context.invoke('cat', ['a b', '*'], { signal: new AbortController().signal, stdin: input, stdout: output, stderr: output });
 void result;
}

import type { CommandContext } from '$PUBLIC';
import type { ShellCommandContext } from '$SHELL';
declare const context: ShellCommandContext;
const base: CommandContext = context;
const result = await context.invoke('true', [], { signal: new AbortController().signal });
const exitCode: number = result.exitCode;
// @ts-expect-error no observed status channel
const observed = result.observedStatus;
// @ts-expect-error no timeout status channel
const timeout = result.timedOut;
void base; void exitCode; void observed; void timeout;
